pub const ROUNDING_MODE_HALF_TO_EVEN: u32 = 0;
pub const ROUNDING_MODE_HALF_AWAY_FROM_ZERO: u32 = 1;
pub const ROUNDING_MODE_TOWARD_ZERO: u32 = 2;
pub const ROUNDING_MODE_TOWARD_NEGATIVE_INFINITY: u32 = 3;
